/* explode: decoder for the PKWARE Data Compression Library stream format (pkdcl.h). Written for this project; not
 * PKWARE's code and not byte-matched (library code: no FUNCTION markers, no matching credit). Behaviour of the
 * original DCL 1.11 that callers can observe is kept: the result codes; a first read of at most 4 bytes is
 * PK_BAD_DATA; input that ends before the end code is PK_ABORT (except inside the end code's last extra bits);
 * output goes to write_buf in 0x1000-byte pieces with the rest at the end (also after an abort); a copy may reach
 * back before the first output byte into the zeroed work buffer (UDataCompression clears it before every call).
 * The code tables below are the format's; their values are those of the original library's data. */
#include <string.h>
#include "pkdcl.h"

