#define LONG_LITERAL 0xffff
#define WINDOW_HISTORY 0x1000           /* output kept for copies */
#define WINDOW_FLUSH 0x2000             /* hand out WINDOW_FLUSH - WINDOW_HISTORY bytes once output reaches this */

typedef struct {
    PKReadFn read;
    PKWriteFn write;
    void *param;
    unsigned long bits;                 /* unread input bits, the next one in bit 0 */
    unsigned int bit_count;
    unsigned int in_pos;
    unsigned int in_len;
    int in_end;                         /* read_buf returned 0 */
    unsigned int mode;
    unsigned int dict_bits;
    unsigned int out_pos;               /* in window: history below WINDOW_HISTORY, new output from there */
    unsigned int long_count;
    unsigned char length_of[256];       /* length code whose bits start the next 8 input bits */
    unsigned char dist_of[256];         /* distance code whose bits start the next 8 input bits */
    unsigned short literal_of[256];     /* ASCII literal whose code starts the next 8 bits, or LONG_LITERAL */
    unsigned char long_literals[256];   /* ASCII literals with codes longer than 8 bits */
    unsigned char in_buf[0x800];
    unsigned char window[WINDOW_FLUSH + PK_MAX_COPY];
} Exploder;

PK_STATIC_ASSERT(exploder_fits, sizeof(Exploder) <= PK_EXPLODE_WORK_SIZE);

/* Tops up the bit buffer to at least 25 bits while input lasts. */
static void Fill(Exploder *s)
{
    while (s->bit_count <= 24) {
        if (s->in_pos == s->in_len) {
            unsigned int size = sizeof(s->in_buf);
            if (s->in_end)
                return;
            s->in_len = s->read((char *)s->in_buf, &size, s->param);
            s->in_pos = 0;
            if (s->in_len == 0) {
                s->in_end = 1;
                return;
            }
        }
        s->bits |= (unsigned long)s->in_buf[s->in_pos++] << s->bit_count;
        s->bit_count += 8;
    }
}

/* The next n (<= 16) bits; bits past the end of the input read as 0. */
static unsigned int Peek(Exploder *s, unsigned int n)
{
    if (s->bit_count < n)
        Fill(s);
    return (unsigned int)(s->bits & ((1UL << n) - 1));
}

/* Consumes n bits; 0 when the input ends first. */
static int Drop(Exploder *s, unsigned int n)
{
    if (s->bit_count < n) {
        Fill(s);
        if (s->bit_count < n)
            return 0;
    }
    s->bits >>= n;
    s->bit_count -= n;
    return 1;
}

/* An n-bit code value c owns the 8-bit lookup slots c, c + 2^n, c + 2 * 2^n, ... */
static void BuildLookup(unsigned char *lookup, const unsigned char *code, const unsigned char *bits, unsigned int n)
{
    unsigned int i, slot;
    for (i = 0; i < n; i++)
        for (slot = code[i]; slot < 256; slot += 1u << bits[i])
            lookup[slot] = (unsigned char)i;
}

static void BuildAsciiLookup(Exploder *s)
{
    unsigned int c, slot;
    for (slot = 0; slot < 256; slot++)
        s->literal_of[slot] = LONG_LITERAL;
    s->long_count = 0;
    for (c = 0; c < 256; c++) {
        if (kAsciiBits[c] <= 8) {
            for (slot = kAsciiCode[c]; slot < 256; slot += 1u << kAsciiBits[c])
                s->literal_of[slot] = (unsigned short)c;
        } else
            s->long_literals[s->long_count++] = (unsigned char)c;
    }
}

/* Decodes one literal (after its 0 flag bit); -1 when the input ends. */
static int ReadLiteral(Exploder *s)
{
    unsigned int c, k, next;
    if (s->mode == PK_BINARY) {
        c = Peek(s, 8);
        return Drop(s, 8) ? (int)c : -1;
    }
    c = s->literal_of[Peek(s, 8)];
    if (c == LONG_LITERAL) {
        next = Peek(s, 16);
        for (k = 0; k < s->long_count; k++) {
            c = s->long_literals[k];
            if ((next & ((1u << kAsciiBits[c]) - 1)) == kAsciiCode[c])
                break;
        }
        if (k == s->long_count)
            return -1;
    }
    return Drop(s, kAsciiBits[c]) ? (int)c : -1;
}

/* Decodes a copy length (after its 1 flag bit): 2..518, PK_END_LENGTH, or 0 when the input ends. */
static unsigned int ReadLength(Exploder *s)
{
    unsigned int code = s->length_of[Peek(s, 8)];
    unsigned int extra = kLengthExtraBits[code];
    unsigned int value;
    if (!Drop(s, kLengthBits[code]))
        return 0;
    value = kLengthBase[code];
    if (extra != 0) {
        value += Peek(s, extra);
        /* the end code counts even when the input stops inside its extra bits */
        if (!Drop(s, extra) && value + PK_MIN_COPY != PK_END_LENGTH)
            return 0;
    }
    return value + PK_MIN_COPY;
}

/* Decodes a copy distance (1..dictionary size) for a copy of `length`; 0 when the input ends. */
static unsigned int ReadDistance(Exploder *s, unsigned int length)
{
    unsigned int high = s->dist_of[Peek(s, 8)];
    unsigned int low_bits = length == PK_MIN_COPY ? 2 : s->dict_bits;
    unsigned int low;
    if (!Drop(s, kDistBits[high]))
        return 0;
    low = Peek(s, low_bits);
    if (!Drop(s, low_bits))
        return 0;
    return ((high << low_bits) | low) + 1;
}

static void WriteOut(Exploder *s, unsigned int count)
{
    unsigned int size = count;
    s->write((char *)s->window + WINDOW_HISTORY, &size, s->param);
}

/* Decodes tokens up to the end code: PK_OK, or PK_ABORT when the input ends first. */
static unsigned int Expand(Exploder *s)
{
    unsigned int result = PK_ABORT;
    s->out_pos = WINDOW_HISTORY;
    for (;;) {
        unsigned int flag = Peek(s, 1);
        if (!Drop(s, 1))
            break;
        if (flag == 0) {
            int c = ReadLiteral(s);
            if (c < 0)
                break;
            s->window[s->out_pos++] = (unsigned char)c;
        } else {
            unsigned int length = ReadLength(s);
            unsigned int distance;
            unsigned char *to, *from;
            if (length == 0)
                break;
            if (length == PK_END_LENGTH) {
                result = PK_OK;
                break;
            }
            distance = ReadDistance(s, length);
            if (distance == 0)
                break;
            to = s->window + s->out_pos;
            from = to - distance;
            s->out_pos += length;
            while (length-- != 0)       /* byte by byte: a copy may overlap its own output */
                *to++ = *from++;
        }
        if (s->out_pos >= WINDOW_FLUSH) {
            WriteOut(s, WINDOW_FLUSH - WINDOW_HISTORY);
            memmove(s->window, s->window + (WINDOW_FLUSH - WINDOW_HISTORY),
                    s->out_pos - (WINDOW_FLUSH - WINDOW_HISTORY));
            s->out_pos -= WINDOW_FLUSH - WINDOW_HISTORY;
        }
    }
    WriteOut(s, s->out_pos - WINDOW_HISTORY);
    return result;
}

unsigned int explode(PKReadFn read_buf, PKWriteFn write_buf, char *work_buf, void *param)
{
    Exploder *s = (Exploder *)work_buf;
    unsigned int size = sizeof(s->in_buf);
    s->read = read_buf;
    s->write = write_buf;
    s->param = param;
    s->in_len = s->read((char *)s->in_buf, &size, s->param);
    if (s->in_len <= 4)
        return PK_BAD_DATA;
    s->in_end = 0;
    s->mode = s->in_buf[0];
    s->dict_bits = s->in_buf[1];
    s->in_pos = 2;
    s->bits = 0;
    s->bit_count = 0;
    if (s->dict_bits < 4 || s->dict_bits > 6)
        return PK_BAD_DICTIONARY;
    if (s->mode != PK_BINARY) {
        if (s->mode != PK_ASCII)
            return PK_BAD_MODE;
        BuildAsciiLookup(s);
    }
    BuildLookup(s->length_of, kLengthCode, kLengthBits, 16);
    BuildLookup(s->dist_of, kDistCode, kDistBits, 64);
    return Expand(s);
}
